from . import pulse_counter
FAN_MIN_TIME = 0.1

class Fan:

    def __init__(self, config, default_shutdown_speed=0.0):
        self.printer = config.get_printer()
        self.last_fan_value = 0.0
        self.last_fan_time = 0.0
        self.max_power = config.getfloat("max_power", 1.0, above=0.0, maxval=1.0)
        self.kick_start_time = config.getfloat("kick_start_time", 0.1, minval=0.0)
        self.off_below = config.getfloat("off_below", default=0.0, minval=0.0,
          maxval=1.0)
        self.on_below = config.getfloat("on_below", default=0.0, minval=0.0,
          maxval=90.0)
        cycle_time = config.getfloat("cycle_time", 0.01, above=0.0)
        hardware_pwm = config.getboolean("hardware_pwm", False)
        shutdown_speed = config.getfloat("shutdown_speed",
          default_shutdown_speed, minval=0.0, maxval=1.0)
        ppins = self.printer.lookup_object("pins")
        self.mcu_fan = ppins.setup_pin("pwm", config.get("pin"))
        self.mcu_fan.setup_max_duration(0.0)
        self.mcu_fan.setup_cycle_time(cycle_time, hardware_pwm)
        shutdown_power = max(0.0, min(self.max_power, shutdown_speed))
        self.mcu_fan.setup_start_value(0.0, shutdown_power)
        self.enable_pin = None
        enable_pin = config.get("enable_pin", None)
        if enable_pin is not None:
            self.enable_pin = ppins.setup_pin("digital_out", enable_pin)
            self.enable_pin.setup_max_duration(0.0)
        self.tachometer = FanTachometer(config)
        self.printer.register_event_handler("gcode:request_restart", self._handle_request_restart)

    def get_mcu(self):
        return self.mcu_fan.get_mcu()

    def set_speed(self, print_time, value):
        if value < self.off_below:
            value = 0.0
        value = max(0.0, min(self.max_power, value * self.max_power))
        if value == self.last_fan_value:
            return
        self.tachometer.rpm_check(value != 0.0)
        print_time = max(self.last_fan_time + FAN_MIN_TIME, print_time)
        if self.enable_pin:
            if value > 0 and self.last_fan_value == 0:
                self.enable_pin.set_digital(print_time, 1)
            elif value == 0:
                if self.last_fan_value > 0:
                    self.enable_pin.set_digital(print_time, 0)
        if value and value < self.max_power:
            if self.kick_start_time:
                if not self.last_fan_value or value - self.last_fan_value > 0.5:
                    self.mcu_fan.set_pwm(print_time, self.max_power)
                    print_time += self.kick_start_time
            value_real = float((self.on_below + value * (100 - self.on_below)) / 100) if value > 0 else 0
            self.mcu_fan.set_pwm(print_time, value_real)
            self.last_fan_time = print_time
            self.last_fan_value = value

    def set_speed_from_command(self, value):
        toolhead = self.printer.lookup_object("toolhead")
        toolhead.register_lookahead_callback(lambda pt: self.set_speed(pt, value))

    def _handle_request_restart(self, print_time):
        self.set_speed(print_time, 0.0)

    def get_status(self, eventtime):
        tachometer_status = self.tachometer.get_status(eventtime)
        return {'speed':self.last_fan_value, 
         'rpm':tachometer_status["rpm"]}


class FanTachometer:

    def __init__(self, config):
        self.printer = printer = config.get_printer()
        self.reactor = printer.get_reactor()
        self._freq_counter = None
        self._fan_name = config.get_name().split()[-1]
        self.gcode = printer.lookup_object("gcode")
        self.rpm_timer = None
        pin = config.get("tachometer_pin", None)
        if pin is not None:
            self.ppr = config.getint("tachometer_ppr", 2, minval=1)
            self.min_rpm = config.getint("min_rpm", 1, minval=1)
            self.error_max_cnt = config.getint("error_max_cnt", 30, minval=1)
            self.rpm = 0.0
            self.error_cnt = 0
            self.error_repeat = False
            poll_time = config.getfloat("tachometer_poll_interval", 0.0015,
              above=0.0)
            sample_time = 1.0
            self._freq_counter = pulse_counter.FrequencyCounter(printer, pin, sample_time, poll_time)

    def rpm_check(self, is_need):
        if self._freq_counter is None:
            return
        self.error_cnt = 0
        self.error_repeat = False
        if is_need:
            if self.rpm_timer is None:
                self.rpm_timer = self.reactor.register_timer(self._do_rpm_query, self.reactor.monotonic())
        elif self.rpm_timer is not None:
            self.reactor.unregister_timer(self.rpm_timer)
            self.rpm_timer = None

    def _do_rpm_query(self, eventtime):
        if self.rpm < self.min_rpm:
            if self.error_cnt >= self.error_max_cnt:
                if not self.error_repeat:
                    self.error_repeat = True
                    self.gcode.respond_error("FanTachometer '%s' rpm %d is below min rpm" % (self._fan_name, self.rpm))
            else:
                self.error_cnt += 1
        else:
            self.error_cnt = 0
            self.error_repeat = False
        return eventtime + 1.0

    def get_status(self, eventtime):
        if self._freq_counter is not None:
            self.rpm = self._freq_counter.get_frequency() * 30.0 / self.ppr
        else:
            self.rpm = None
        return {"rpm": (self.rpm)}


class PrinterFan:

    def __init__(self, config):
        self.fan = Fan(config)
        gcode = config.get_printer().lookup_object("gcode")
        gcode.register_command("M106", self.cmd_M106)
        gcode.register_command("M107", self.cmd_M107)

    def get_status(self, eventtime):
        return self.fan.get_status(eventtime)

    def cmd_M106(self, gcmd):
        value = gcmd.get_float("S", 255.0, minval=0.0) / 255.0
        self.fan.set_speed_from_command(value)

    def cmd_M107(self, gcmd):
        self.fan.set_speed_from_command(0.0)


def load_config(config):
    return PrinterFan(config)

